from pathlib import Path
import re

path = Path(r"E:\trip\france_trip_guide_2026.html")
text = path.read_text(encoding="utf-8")


def replace_article(day_id, new_html):
    global text
    pattern = rf'<article class="day" id="{day_id}">.*?</article>'
    text2, n = re.subn(pattern, new_html, text, count=1, flags=re.S)
    if n != 1:
        raise RuntimeError(f"{day_id}: {n} matches")
    text = text2

text = text.replace(
    '长途交通以出票信息为准；TER、ZOU、杭州—上海高铁在出发前再次确认具体班次。',
    '长途交通以出票信息为准；区域铁路、公交与机场交通在出发前再次确认具体班次。'
)

